<script setup lang="ts">
import { ref,computed,onMounted,onUnmounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import {activeAppearance,systemDark,rememberAppearance,appearanceEpoch} from '../ui/theme'
import AdminContent from '../admin/AdminContent.vue'
import { request } from '../api'
import { blankSite,type Site } from '../blog/types'
import {colorStyle,customKeys,appearanceAttrs} from '../blog/colors'
const props=defineProps<{preview?:import('../blog/types').Appearance;previewRecordId?:string}>()
const route=useRoute(),router=useRouter(),site=ref<Site>(blankSite())
const appearance=computed(()=>props.preview||activeAppearance.value)
const dark=computed(()=>appearance.value.mode==='dark'||appearance.value.mode==='system'&&systemDark.value)
let alive=true;onUnmounted(()=>{alive=false})
onMounted(async()=>{try{const epoch=appearanceEpoch();const result=await request('/blog/site');if(!alive)return;site.value=result;if(!props.preview)rememberAppearance(site.value.appearance,epoch)}catch{/* existing route guards enforce authorization */}})
</script>
<template><main class="blog lj-theme writing-page" v-bind="appearanceAttrs(appearance)" :data-mode="dark?'dark':'light'" :data-custom="customKeys(appearance,dark?'dark':'light')" :style="colorStyle(appearance,dark?'dark':'light')"><header class="writing-header"><RouterLink to="/">{{site.title}} · 返回阅读</RouterLink><span>私人写作空间</span><RouterLink to="/admin/content">内容管理</RouterLink></header><div class="writing-canvas"><p class="blog-kicker">A STORY OF YOUR OWN</p><h1 v-if="!route.params.id">写下值得记住的生活</h1><RouterLink v-if="!route.params.id" class="button" to="/write/ai">AI 创作新文章</RouterLink><AdminContent immersive :preview-only="!!preview" :publish-intent="route.query.publish==='1'" :initial-template-id="typeof route.query.template==='string'?route.query.template:undefined" :record-id="previewRecordId||(typeof route.params.id==='string'?route.params.id:undefined)" @exit="router.push('/')"/></div></main></template>
