ground:var(--paper,var(--ui-card));padding:16px 0;border-top:1px solid var(--line,var(--ui-line))}.immersive-writing .save-toolbar{flex-wrap:wrap}.immersive-writing fieldset{min-width:0}.immersive-writing input,.immersive-writing textarea,.immersive-writing select{max-width:100%}@media(max-width:600px){.writing-canvas{padding:24px 16px 70px}.writing-header{padding:16px;font-size:14px}.writing-header>span{display:none}.writing-canvas>h1{font-size:24px}.immersive-writing .writing-main input:not([type=date]){font-size:25px}}
</style>

